public class Ex04RelaxedBinding {
    // 规范化：全大写视为环境变量式先转小写；下划线转短横线；驼峰前插短横线
    static String canonical(String key) {
        String k = key;
        if (k.equals(k.toUpperCase())) k = k.toLowerCase();
        k = k.replace('_', '-');
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k.length(); i++) {
            char c = k.charAt(i);
            if (Character.isUpperCase(c)) {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '-') sb.append('-');
                sb.append(Character.toLowerCase(c));
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String[] keys = {"my-name", "myName", "my_name", "MY_NAME", "MYNAME", "my.name", "app.myName"};
        for (String k : keys) {
            System.out.println(k + "  ->  " + canonical(k));
        }
        System.out.println("MYNAME equals my-name ? " + canonical("MYNAME").equals(canonical("my-name")));
    }
}
